a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: train_coxph.R <dev> <val> <out> [vars]");if(!requireNamespace("survival",quietly=TRUE))stop("Install survival");tr<-read.csv(a[1],check.names=FALSE);va<-read.csv(a[2],check.names=FALSE);out<-a[3];v<-if(length(a)>=4)strsplit(a[4],",",TRUE)[[1]]else setdiff(names(tr),c("Time","Event"));dir.create(out,recursive=TRUE,showWarnings=FALSE);f<-as.formula(paste("survival::Surv(Time,Event)~",paste(v,collapse="+")));fit<-survival::coxph(f,tr,x=TRUE,y=TRUE,model=TRUE);for(nm in c("development","validation")){d<-if(nm=="development")tr else va;write.csv(data.frame(Time=d$Time,Event=d$Event,Coxph=as.numeric(predict(fit,d,type="lp"))),file.path(out,paste0(nm,"_coxph_predictions.csv")),row.names=FALSE)};write.csv(as.data.frame(survival::cox.zph(fit)$table),file.path(out,"ph_test.csv"));saveRDS(fit,file.path(out,"coxph_model.rds"))
